head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 > 개발자모드(F12) 실행 > Elements로 그리드뷰 클릭한다.
    //1. After executing the sample file, click> Grid View with Developer Mode (F12) Execution> Elements.
    //Verify 1. 그리드뷰가 시작되는(가장 바깥부분) class에 w2grid_readonly_outer와 w2grid_disabled_outer가 보여진다.
    //1. The w2grid_readonly_outer and w2grid_disabled_outer are shown in the class where the grid view starts (the outermost part).
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridview1').hasClass('w2grid_readonly_outer')", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridview1').hasClass('w2grid_disabled_outer')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    gridview1.setDisabled(true);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 21-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
